import {createWorkflowUI} from './workflow-ui.js';
import {createSeedState} from './seeds.js';
import {calculate,analyze,createRevision,validateRevision,SENSORY_GROUPS,SCENARIOS} from './domain.js';
import {mountScene,visualSpec} from './scene.js';
import {loadState,saveState,uploadAttachment,importProducts} from './data-source.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), clone=v=>structuredClone(v);
const num=(v,d=2)=>v===null||v===undefined||!Number.isFinite(Number(v))?'Нет данных':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:d}).format(v);
const uid=()=>crypto.randomUUID(), date=v=>new Date(v).toLocaleString('ru-RU'), now=()=>new Date().toISOString(), localTime=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);
const tabs={recipe:'Рецепт',sensory:'Вкус и текстура',trials:'Испытания',docs:'Документы',assistant:'Помощник',approval:'Утверждение'};
const ops={coagulate:'Сквашивание',drain:'Отделение сыворотки',press:'Прессование',mix:'Смешивание',layer:'Послойная сборка',puree:'Измельчение в пюре',heat:'Нагрев',cool:'Охлаждение'};
const stages=['Концепция','Рецептура','Испытания','Утверждение'];
const columns=[['title','Название'],['author','Создатель'],['updated','Обновлено'],['ingredients','Сырьё'],['nutrition','КБЖУ'],['physical','ФХП'],['allergens','Аллергены'],['mark','Честный знак'],['stage','Статус'],['trials','Испытания']];
let state,selectedProduct=null,selectedRevision=null,scene=null,busy=false,search='',filter='',group=Object.keys(SENSORY_GROUPS)[0],scenario=Object.keys(SCENARIOS)[0],docFilter='',chat=[],candidate=null,calcOptions={},editor=null;
let incomingEditing=null,correctingCandidate=null;
const main=$('#main'),modal=$('#modal');
try{const selection=JSON.parse(localStorage.getItem('digital-product-selection')||'null');selectedProduct=selection?.product||null;selectedRevision=selection?.revision||null}catch{}
function rememberSelection(){try{localStorage.setItem('digital-product-selection',JSON.stringify({product:selectedProduct,revision:selectedRevision}))}catch{}}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000)}
function errorMessage(e){if(e.status===409||String(e.message).includes('409'))return 'Данные уже изменены в другом окне. Ваш ввод сохранён в открытой форме. Закройте её и нажмите «Обновить данные», затем повторите изменение.';return e.message||'Не удалось выполнить действие. Проверьте доступность локального сервера.'}
function showError(e){const box=modal.open?modal.querySelector('.dialog-error'):$('#page-error');if(box){box.hidden=false;box.textContent=errorMessage(e)}else toast(errorMessage(e))}
const product=()=>state.products.find(p=>p.id===selectedProduct)||state.products[0];
const revision=()=>product()?.revisions.find(r=>r.id===selectedRevision)||product()?.revisions.at(-1);
const tab=()=>location.hash.slice(1)||'library';
const role=()=>'rd';
const frozen=()=>['review','final','approved'].includes(revision()?.approval?.status);
function canEdit(){return !frozen()&&role()!=='viewer'}
function field(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function option(value,label,chosen){return `<option value="${esc(value)}" ${value===chosen?'selected':''}>${esc(label)}</option>`}
function openDialog(title,body,actions='',wide=false){modal.className=wide?'wide-dialog':'';modal.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-action="close" aria-label="Закрыть">×</button></div><div class="dialog-error error" role="alert" hidden></div>${body}<div class="dialog-actions">${actions}<button data-action="close">Закрыть</button></div>`;modal.showModal()}
function closeDialog(){modal.close();editor=null;incomingEditing=null;correctingCandidate=null}
async function persist(next,message,operationRole=role()){if(busy)throw Error('Сохранение уже выполняется. Дождитесь завершения.');busy=true;$('#save-status').textContent='Сохранение…';try{state=await saveState(next,operationRole);$('#save-status').textContent='Сохранено '+new Date().toLocaleTimeString('ru-RU');if(message)toast(message);return state}catch(e){$('#save-status').textContent='Не сохранено';throw e}finally{busy=false}}
async function changeRevision(fn,message){if(!canEdit())throw Error('Пакет этой редакции зафиксирован. Создайте новую редакцию для изменений.');const next=clone(state),p=next.products.find(p=>p.id===product().id),r=p.revisions.find(r=>r.id===revision().id);await fn(r,p,next);await persist(next,message);render()}
function header(){const p=product(),r=revision();return `<a href="#library" class="muted">← Библиотека</a><div class="heading"><div><h1>${esc(p.title)}</h1><div class="revision-line"><select id="revision-select" aria-label="Редакция">${[...p.revisions].reverse().map(x=>option(x.id,`Редакция ${x.version} · ${x.changeNote||x.description||'Без комментария'}`,r.id)).join('')}</select></div></div><div class="actions"><button data-action="refresh" class="ghost">Обновить данные</button><button data-action="edit-recipe" ${role()==='viewer'?'disabled':''}>Новая редакция</button></div></div><nav class="tabs" aria-label="Разделы продукта">${Object.entries(tabs).map(([id,label])=>`<a class="tab ${tab()===id?'active':''}" href="#${id}" ${tab()===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`}
function render(){scene?.dispose();scene=null;if(!state)return;main.innerHTML=`<div id="page-error" class="error" role="alert" hidden></div>`+(tab()==='library'||!product()?library():header()+({recipe:recipeView,sensory:sensoryView,trials:trialsView,docs:docsView,assistant:assistantView,approval:approvalView}[tab()]||recipeView)()+(tab()==='recipe'?workflowUI.recipePanel():''));if(tab()==='recipe'&&product()){const container=$('#scene');try{scene=mountScene(container,revision());if(scene.error){const note=document.createElement('p');note.className='notice';note.textContent=scene.error;container.after(note)}}catch(e){container.innerHTML='<p class="notice">3D недоступно: '+esc(e.message)+'</p>'}}}
function library(){const counts=Object.fromEntries(stages.map(s=>[s,state.products.filter(p=>p.stage===s).length])),max=Math.max(1,...Object.values(counts));const rows=state.products.filter(p=>(!filter||p.stage===filter)&&`${p.title} ${p.code} ${p.id} ${(p.tags||[]).join(' ')}`.toLowerCase().includes(search.toLowerCase().replace(/^#/,'')));let cols=state.settings?.columns||[];if(!cols.length)cols=columns.map(([id])=>({id,shown:true}));cols=cols.map(c=>typeof c.id==='number'?{...c,id:columns[c.id]?.[0]}:c).filter(c=>c.shown&&columns.some(([id])=>id===c.id));return `<div class="library-page"><div class="heading library-heading"><h1>Библиотека продуктов</h1><button class="dark" data-action="import">Импортировать JSON</button></div><div class="toolbar library-toolbar"><input id="search" type="search" value="${esc(search)}" placeholder="Поиск по названию, ID или тегу" aria-label="Поиск продуктов"><select id="stage" aria-label="Этап">${option('','Все этапы',filter)+stages.map(s=>option(s,s,filter)).join('')}</select></div><section class="card recipes-card"><div class="row spread library-card-heading"><h2>Рецептуры</h2><button data-action="columns">Колонки</button></div><div class="table-wrap"><table class="library-table"><thead><tr>${cols.map(c=>`<th>${columns.find(([id])=>id===c.id)[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(p=>{const r=p.revisions.at(-1),c=calculate(r);const values={title:`<strong>${esc(p.title)}</strong><span class="id">#${esc(p.code||p.id)}</span>`,author:esc(p.author||'Не указан'),updated:date(r.createdAt),ingredients:`${r.ingredients.length} компонентов`,nutrition:c.nutrition?`${num(c.nutrition.kcal)} ккал / 100 г`:'Нет данных',physical:'Нет замеров',allergens:esc(c.allergens.join(', ')||'Требует проверки'),mark:'Не сформирован',stage:esc(p.stage),trials:`${r.trials?.length||0} планов`};return `<tr data-product="${esc(p.id)}">${cols.map(c=>`<td>${c.id==='title'?`<a href="#recipe" data-product="${esc(p.id)}">${values[c.id]}</a>`:values[c.id]}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>${rows.length?'':'<p class="empty">Продукты не найдены. Измените запрос или этап.</p>'}</section>${workflowUI.incomingPanel()}<section class="card stage-card"><h2>Продукты по этапам</h2><p class="muted stage-subtitle">Число продуктов на текущем этапе</p><div class="stage-chart">${stages.map(s=>`<button class="stage-row" data-stage="${s}" aria-label="Фильтр ${s}: ${counts[s]}"><span class="stage-label">${s}</span><span class="stage-track"><span style="width:${counts[s]/max*100}%"></span></span><span class="stage-count">${counts[s]}</span></button>`).join('')}</div></section></div>`}
function recipeView(){const r=revision(),c=calculate(r,calcOptions),v=visualSpec(r);return `<div class="split"><div class="scene-wrap"><div id="scene" class="scene"></div><small>Визуальная модель редакции ${esc(r.version)} · ${esc(v.structure)}</small><div class="notice">${esc(v.reason||'Геометрия построена по составу и порядку операций. Это визуальная интерпретация, без подтверждения физических свойств.')}</div></div><div><section class="card"><div class="row spread"><h2>Состав продукта</h2><button data-action="edit-recipe">Редактировать</button></div><p class="muted">${esc(r.description||"Описание редакции не задано")}</p><div class="metrics"><div class="metric"><small>Загрузка, кг</small><strong>${num(c.inputKg,4)}</strong></div><div class="metric"><small>Выход, кг</small><strong>${num(c.outputKg,4)}</strong></div><div class="metric"><small>Порция, г</small><strong>${num(c.portionG)}</strong></div><div class="metric"><small>Энергия / 100 г</small><strong>${c.nutrition?num(c.nutrition.kcal):'Нет данных'}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Ингредиент</th><th>Доля</th><th>Эквивалент на порцию, г</th><th>Эквивалент состава, кг</th><th>Загрузка сырья, кг</th><th>Стоимость сырья, ₽</th></tr></thead><tbody>${c.lines.map(i=>`<tr><td><strong>${esc(i.name)}</strong><br><small>${esc(i.phaseId)}</small></td><td>${num(i.share*100)}%</td><td>${num(i.gramsPerPortion)}</td><td>${num(i.batchKg,4)}</td><td>${num(i.productionKg,4)}</td><td>${num(i.productionCost)}</td></tr>`).join('')}</tbody></table></div><p><b>Потребность в загрузке: ${num(c.requiredInputKg,4)} кг. ${c.costComplete?'Стоимость сырья':'Известная часть стоимости сырья'}: ${num(c.productionCostTotal)} ₽</b></p><p class="field-note">Эквивалент состава ${num(c.finishedKg)} кг, стоимость эквивалента ${num(c.costTotal)} ₽. Эквивалент не является закупочной загрузкой при отделении потоков.</p>${c.missingPrices.length?`<p class="notice">Нет цен: ${esc(c.missingPrices.join(', '))}. Итог не является полной стоимостью.</p>`:''}<div class="actions"><button data-action="recalculate">Пересчитать количество</button><button data-action="label">Черновик этикетки</button></div></section></div></div><div class="split"><section class="card"><div class="row spread"><h2>Приготовление</h2><button data-action="edit-recipe">Редактировать технологию</button></div>${r.processSteps.map((s,i)=>`<div class="operation"><b>${i+1}</b><div><strong>${esc(ops[s.type]||s.type)}</strong><br><small>${s.temperatureC==null?'':num(s.temperatureC)+' °C · '}${s.durationMin==null?'':num(s.durationMin)+' мин'} ${esc(s.description||'')}</small></div></div>`).join('')||'<p>Операции не заданы</p>'}</section><section class="card"><h2>Пищевая ценность и ограничения</h2><p>На 100 г: ${c.nutrition?`белки ${num(c.nutrition.protein)} г · жиры ${num(c.nutrition.fat)} г · углеводы ${num(c.nutrition.carbs)} г`:'Спецификации или модель выхода не позволяют рассчитать КБЖУ.'}</p><p><b>Аллергены:</b> ${esc(c.allergens.join(', ')||'Не установлены. Требуется проверка спецификаций.')}</p>${c.warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<small>Расчёт использует спецификации этой редакции. Следовое присутствие аллергенов проверяется отдельно.</small></section></div>`}
function editorDialog(initial=null){if(!initial){incomingEditing=null;correctingCandidate=null;}editor=clone(initial||revision());openDialog('Состав и технология · новая редакция',`<p class="notice">Исходная редакция ${esc(revision().version)} остаётся доступной. Изменение фиксируется одним общим сохранением.</p>${field("Описание продукта / редакции","revision-description",editor.description||"")}${field('Комментарий изменения','revision-note','','text','required')}<h3>Ингредиенты</h3><div id="ingredient-editor"></div><div class="actions"><button data-action="add-ingredient">+ Новый ингредиент</button><button data-action="ingredient-catalog">Каталог спецификаций</button></div><div id="catalog-panel"></div><hr><h3>Технологические операции</h3><div id="operation-editor"></div><button data-action="add-operation">+ Добавить операцию</button><hr><div class="grid">${field('Выход готового продукта, кг','outputKg',editor.output?.massKg??'','number','min="0.001" step="any"')}${`<label>Метод выхода<select name="outputMethod">${option("mass_conservation","Сохранение массы",editor.output?.method)}${option("confirmed_mass_balance","Баланс с отделяемыми потоками",editor.output?.method)}${option("unknown","Выход не подтверждён",editor.output?.method)}</select></label>`}${field("Отделяемые потоки суммарно, кг","lossKg",(editor.output?.lossStreams||[]).reduce((a,b)=>a+b.massKg,0),"number",'min="0" step="any"')}<label class="inline-check"><input name="outputConfirmed" type="checkbox" ${editor.output?.confirmed?"checked":""}>Подтверждаю основание выхода и массовый баланс</label>${field('Упаковка','packaging',editor.packaging?.type||'')}${field('Порция, г','portionG',editor.packaging?.portionG??'','number','min="0.001" step="any"')}</div>`,`<button class="dark" data-action="save-recipe">Сохранить новую редакцию</button>`,true);drawEditor()}
function drawEditor(){const rows=editor.ingredients;$('#ingredient-editor').innerHTML=`<div class="table-wrap"><table class="editor"><thead><tr><th>Название</th><th>Масса, кг</th><th>Фаза</th><th>Цена, ₽/кг</th><th>Спецификация</th><th></th></tr></thead><tbody>${rows.map((i,n)=>`<tr><td><input data-ing="${n}" data-key="name" value="${esc(i.name)}" aria-label="Название ингредиента ${n+1}"></td><td><input data-ing="${n}" data-key="massKg" type="number" min="0.0001" step="any" value="${i.massKg}" aria-label="Масса ${n+1}"></td><td><input data-ing="${n}" data-key="phaseId" value="${esc(i.phaseId)}" aria-label="Фаза ${n+1}"></td><td><input data-ing="${n}" data-key="pricePerKg" type="number" min="0" step="any" value="${i.pricePerKg??''}" aria-label="Цена ${n+1}"></td><td><button class="small" data-spec="${n}">КБЖУ и свойства</button></td><td><button class="small" data-remove-ing="${n}" aria-label="Удалить ингредиент ${n+1}">×</button></td></tr>`).join('')}</tbody></table></div>`;$('#operation-editor').innerHTML=editor.processSteps.map((s,i)=>`<div class="point"><div class="row spread"><b>${i+1}. ${esc(ops[s.type]||s.type)}</b><span><button class="small" data-move-op="${i}" data-direction="-1" ${i===0?'disabled':''}>↑</button> <button class="small" data-move-op="${i}" data-direction="1" ${i===editor.processSteps.length-1?'disabled':''}>↓</button> <button class="small" data-remove-op="${i}">Удалить</button></span></div><div class="grid"><label>Тип<select data-op="${i}" data-key="type">${Object.entries(ops).map(([id,l])=>option(id,l,s.type)).join('')}</select></label><label>Фаза<input data-op="${i}" data-key="phaseId" value="${esc(s.phaseId||'')}"></label><label>Температура, °C<input type="number" step="any" data-op="${i}" data-key="temperatureC" value="${s.temperatureC??''}"></label><label>Время, мин<input type="number" min="0" step="any" data-op="${i}" data-key="durationMin" value="${s.durationMin??''}"></label><label class="full">Описание<input data-op="${i}" data-key="description" value="${esc(s.description||'')}"></label></div></div>`).join('')}
function readEditor(){for(const input of modal.querySelectorAll('[data-ing]')){const obj=editor.ingredients[+input.dataset.ing],key=input.dataset.key;obj[key]=['massKg','pricePerKg'].includes(key)?(input.value===''?null:Number(input.value)):input.value.trim()}for(const input of modal.querySelectorAll('[data-op]')){const obj=editor.processSteps[+input.dataset.op],key=input.dataset.key;obj[key]=['temperatureC','durationMin'].includes(key)?(input.value===''?null:Number(input.value)):input.value.trim()}}
async function saveRecipe(){readEditor();editor.output={...editor.output,massKg:modal.querySelector('[name=outputKg]').value===''?null:Number(modal.querySelector('[name=outputKg]').value),method:modal.querySelector('[name=outputMethod]').value,confirmed:modal.querySelector('[name=outputConfirmed]').checked,lossStreams:[{name:'Отделяемые потоки',massKg:Number(modal.querySelector('[name=lossKg]').value)}]};editor.packaging={type:modal.querySelector('[name=packaging]').value.trim(),portionG:Number(modal.querySelector('[name=portionG]').value)};editor.description=modal.querySelector('[name=revision-description]').value.trim();const note=modal.querySelector('[name=revision-note]').value.trim();if(!note)throw Error('Добавьте комментарий к новой редакции.');const errors=validateRevision(editor);if(errors.length)throw Error(errors.join('\n'));if(incomingEditing){const result=await workflowRequest('/api/imports/dossiers/'+incomingEditing.id+'/complete',{draft:editor,expectedVersion:state.version});state=result.state;selectedProduct=result.productId;selectedRevision=result.revisionId;rememberSelection()}else if(correctingCandidate){await workflowUI.decide('correct',editor)}else await addRevision(editor,note);closeDialog();render()}
async function addRevision(draft,note){const next=clone(state),p=next.products.find(p=>p.id===product().id),r=createRevision(p,draft,note);r.changeNote=note;r.description=draft.description||note;p.revisions.push(r);p.stage='Рецептура';selectedRevision=r.id;rememberSelection();await persist(next,'Новая редакция сохранена')}
function recalcDialog(){const r=revision(),c=calculate(r,calcOptions);openDialog('Пересчёт партии',`<form id="recalc-form"><div class="grid">${field('Масса порции, г','portionG',c.portionG||100,'number','min="0.001" step="any" required')}${field('Количество упаковок','quantity',c.quantity||100,'number','min="1" step="1" required')}</div></form><p class="notice">Расчёт показывает потребность для выбранного количества. Состав редакции не изменяется. При неизвестном выходе готовая масса не подтверждается.</p>`,`<button class="dark" data-action="apply-recalc">Пересчитать</button>`)}
function sensoryValue(v){return typeof v==='object'&&v!==null?v.value:v}
function radar(names,a,s){const n=names.length,c=150,r=100,pt=(i,v)=>[c+Math.sin(i*2*Math.PI/n)*r*v/5,c-Math.cos(i*2*Math.PI/n)*r*v/5];const series=[['#222',a.scores,false],['#888',s.targets,true],['#aaa',s.measurements,false],['#555',s.corrections,true]];return `<svg class="radar" viewBox="0 0 300 300" role="img" aria-label="Сенсорный профиль, шкала от 0 до 5">${[1,2,3,4,5].map(v=>`<polygon points="${names.map((_,i)=>pt(i,v).join(',')).join(' ')}" fill="none" stroke="#e4e4e4"/>`).join('')}${names.map((name,i)=>{const p=pt(i,5),t=pt(i,6.1);return `<line x1="150" y1="150" x2="${p[0]}" y2="${p[1]}" stroke="#eee"/><text x="${t[0]}" y="${t[1]}" text-anchor="middle" font-size="8">${esc(name.length>21?name.slice(0,19)+'…':name)}</text>`}).join('')}${series.map(([color,values,dashed])=>{const valid=names.map(k=>sensoryValue(values?.[k]));return (valid.every(v=>v!=null)?`<polygon points="${valid.map((v,i)=>pt(i,v).join(',')).join(' ')}" fill="none" stroke="${color}" ${dashed?'stroke-dasharray="4 3"':''}/>`:'')+valid.map((v,i)=>v==null?'':`<circle cx="${pt(i,v)[0]}" cy="${pt(i,v)[1]}" r="3" fill="${color}"><title>${esc(names[i])}: ${num(v)}</title></circle>`).join('')}).join('')}</svg>`}
function sensoryView(){const r=revision(),a=analyze(r),s=r.sensory||{},names=SENSORY_GROUPS[group]||[];return `<div class="row spread"><div><h2>Вкус и текстура</h2><small>Редакция ${esc(r.version)} · ${esc(a.method)} · вход ${esc(a.inputHash)}</small></div><button data-action="sensory-edit" ${canEdit()?'':'disabled'}>Уточнить профиль</button></div><p class="notice">Авто - эвристический индекс по составу и технологии, не результат дегустации. Цель, экспертная коррекция и фактическое измерение хранятся отдельно. Пустое значение означает отсутствие оценки.</p><div class="chips toolbar">${Object.keys(SENSORY_GROUPS).map(g=>`<button class="chip ${g===group?'active':''}" data-group="${esc(g)}">${esc(g)}</button>`).join('')}</div><section class="card"><div class="sensory-layout"><div>${radar(names.slice(0,10),a,s)}<div class="legend"><span><i class="dot auto"></i>Авто</span><span><i class="dot target"></i>Цель</span><span><i class="dot measure"></i>Измерение</span><span>⋯ Коррекция</span></div><p class="field-note">На диаграмме до 10 осей; полный перечень справа. Контуры с пропусками не замыкаются.</p></div><div class="table-wrap"><table class="sensory-table"><thead><tr><th>Признак · шкала 0-5</th><th>Авто</th><th>Цель</th><th>Коррекция</th><th>Измерение</th></tr></thead><tbody>${names.map(k=>`<tr><td>${esc(k)}</td><td>${a.scores[k]==null?'Не оценено':num(a.scores[k])}</td><td>${s.targets?.[k]==null?'Не задано':num(sensoryValue(s.targets[k]))}</td><td title="${esc(s.corrections?.[k]?.reason||'')}">${s.corrections?.[k]==null?'Не уточнено':num(sensoryValue(s.corrections[k]))}</td><td title="${esc(s.measurements?.[k]?.sampleId||'')}">${s.measurements?.[k]==null?'Нет замера':num(sensoryValue(s.measurements[k]))}</td></tr>`).join('')}</tbody></table>${group==='Ощущения при употреблении'?`<p class="notice"><b>Фактическая длительность послевкусия:</b> ${s.aftertasteMeasurement?.seconds==null?'Нет замера':num(s.aftertasteMeasurement.seconds)+' с'}${s.aftertasteMeasurement?.seconds==null?'':`<br><small>Метод: ${esc(s.aftertasteMeasurement.method)} · Образец: ${esc(s.aftertasteMeasurement.sampleId)} · ${date(s.aftertasteMeasurement.date)}</small>`}</p>`:''}</div></div></section><div class="split"><section class="card"><h3>Основание</h3>${a.evidence.map(x=>`<p>${esc(x)}</p>`).join('')}</section><section class="card"><h3>Ограничения модели</h3>${a.limitations.map(x=>`<p>${esc(x)}</p>`).join('')}</section></div>`}
function sensoryDialog(){const r=revision(),s=r.sensory||{},names=SENSORY_GROUPS[group];openDialog('Уточнение · '+group,`<form id="sensory-form"><label>Слой данных<select name="layer"><option value="targets">Целевой профиль</option><option value="corrections">Экспертная коррекция</option><option value="measurements">Фактическое измерение</option></select></label><p class="notice">Шкала 0-5. Пустое поле очищает значение выбранного слоя, 0 означает отсутствие признака.</p><div class="grid">${names.map((name,i)=>field(name,'score-'+i,sensoryValue(s.targets?.[name])??'','number','min="0" max="5" step="0.1"')).join('')}${group==='Ощущения при употреблении'?field('Длительность послевкусия, с','aftertasteSeconds',s.aftertasteMeasurement?.seconds??'','number','min="0" step="any" disabled'):''}${field('Причина / условия' ,'reason','','text','required')}${field('Методика и версия','method') }<label>План и образец (для измерения)<select name="sample"><option value="">Выберите образец</option>${(r.trials||[]).flatMap(t=>(t.samples||[]).map(sample=>option(t.id+'|'+(sample.id||sample),`${t.name} · ${sample.code||sample.id||sample}`,''))).join('')}</select></label></div></form>`,`<button class="dark" data-action="save-sensory">Сохранить слой</button>`,true);modal.querySelector('[name=layer]').onchange=e=>{names.forEach((name,i)=>modal.querySelector(`[name=score-${i}]`).value=sensoryValue(s[e.target.value]?.[name])??'');const seconds=modal.querySelector('[name=aftertasteSeconds]');if(seconds)seconds.disabled=e.target.value!=='measurements'}}
async function saveSensory(){const f=new FormData($('#sensory-form')),layer=f.get('layer'),reason=f.get('reason').trim(),method=f.get('method').trim(),sample=f.get('sample');if(!reason)throw Error('Укажите причину или условия оценки.');if(layer==='measurements'&&(!sample||!method))throw Error('Для измерения выберите образец и укажите методику.');const rawSeconds=f.get('aftertasteSeconds'),seconds=rawSeconds===null||rawSeconds===''?null:Number(rawSeconds);if(layer==='measurements'&&group==='Ощущения при употреблении'&&seconds!==null&&(!Number.isFinite(seconds)||seconds<0))throw Error('Длительность послевкусия должна быть неотрицательным числом секунд.');const values={};SENSORY_GROUPS[group].forEach((name,i)=>{const raw=f.get('score-'+i);if(raw==='')return;const v=Number(raw);if(!Number.isFinite(v)||v<0||v>5)throw Error('Интенсивность должна быть в пределах 0-5.');values[name]=layer==='targets'?v:{value:v,reason,method,author:role(),date:now(),trialId:sample?.split('|')[0],sampleId:sample?.split('|')[1]}});await changeRevision(r=>{r.sensory??={};r.sensory[layer]??={};if(layer==='measurements'&&group==='Ощущения при употреблении')r.sensory.aftertasteMeasurement={seconds,method,reason,author:role(),date:now(),trialId:sample.split('|')[0],sampleId:sample.split('|')[1]};for(const name of SENSORY_GROUPS[group])delete r.sensory[layer][name];Object.assign(r.sensory[layer],values);r.sensory.history??=[];r.sensory.history.push({layer,group,values:clone(values),...(layer==='measurements'&&group==='Ощущения при употреблении'?{aftertasteMeasurement:clone(r.sensory.aftertasteMeasurement)}:{}),reason,at:now(),author:role()})},'Сенсорный слой сохранён');closeDialog()}
function trialsView(){const r=revision(),sc=SCENARIOS[scenario],trials=(r.trials||[]).filter(t=>t.scenario===scenario);return `<div class="row spread"><div><h2>Испытания</h2><p class="muted">Планы, контрольные точки и фактические измерения редакции ${esc(r.version)}</p></div><button class="dark" data-action="new-trial" ${canEdit()?'':'disabled'}>+ Создать план</button></div><div class="chips toolbar">${Object.entries(SCENARIOS).map(([id,x])=>`<button class="chip ${scenario===id?'active':''}" data-scenario="${id}">${esc(x.name)}</button>`).join('')}</div><p class="notice">${esc(sc.limitation)} Физический прогноз без калиброванной модели не выполняется. План и сохранённые значения не подтверждают безопасность и срок годности.</p>${trials.map(t=>`<section class="card"><div class="row spread"><div><h2>${esc(t.name)}</h2><span class="badge">${esc(t.status==='ready'?'План готов':t.status==='completed'?'Завершён':'Черновик')}</span></div><div class="actions"><button data-edit-trial="${esc(t.id)}" ${canEdit()?'':'disabled'}>Изменить план</button><button data-add-point="${esc(t.id)}" ${canEdit()?'':'disabled'}>Добавить точку</button><button data-ready-trial="${esc(t.id)}" ${canEdit()?'':'disabled'}>Проверить план</button></div></div><p>${esc(t.goal)}</p><small>Партия ${esc(t.batch)} · ${esc(t.samples.map(s=>s.code||s.id).join(', '))} · ${esc(t.conditions.temperatureC)} °C · ${esc(t.conditions.duration)} ${esc(t.conditions.unit||'ч')} · Ответственный: ${esc(t.owner)}</small><p class="field-note">Методика: ${esc(t.method||'Не задана')} · Упаковка: ${esc(t.packaging||'Не задана')}</p>${(t.points||[]).map(pt=>`<div class="point"><div class="row spread"><h3>${esc(pt.indicator)} · ${esc(pt.offset)} ${esc(pt.unit)} от начала</h3><button class="small" data-measure="${esc(t.id)}|${esc(pt.id)}" ${canEdit()?'':'disabled'}>Ввести замер</button></div><p class="field-note">Метод: ${esc(pt.method)} · Критерий: ${esc(pt.criterion||'Не задан')} · Образец: ${esc(pt.sampleId)}</p>${pt.measurements?.length?`<div class="table-wrap"><table><thead><tr><th>Факт</th><th>Время</th><th>Автор</th><th>Метод</th><th>Протокол</th></tr></thead><tbody>${pt.measurements.map(m=>`<tr><td>${esc(m.value)} ${esc(m.unit)}</td><td>${date(m.at)}</td><td>${esc(m.author)}</td><td>${esc(m.method)}</td><td>${m.documentId?`<a href="${esc(state.documents.find(d=>d.id===m.documentId)?.url||'#')}" download>Скачать</a>`:'Не приложен'}</td></tr>`).join('')}</tbody></table></div>`:'<small>Фактических измерений пока нет</small>'}</div>`).join('')||'<p class="empty">Добавьте контрольные точки плана.</p>'}</section>`).join('')||'<section class="card empty">В этом сценарии ещё нет планов. Создайте первый план.</section>'}`}
function trialDialog(id=null){openDialog('Новый план · '+SCENARIOS[scenario].name,`<form id="trial-form"><div class="grid">${field('Название плана','name','','text','required')}${field('Цель / проверяемая гипотеза','goal','','text','required')}${field('Партия','batch','','text','required')}${field('Коды образцов через запятую','samples','','text','required')}${field('Температура, °C','temperatureC','','number','step="any" required')}${field('Длительность, ч','duration','','number','min="0.01" step="any" required')}${field('Начало отсчёта','startAt',localTime(),'datetime-local','required')}${field('Ответственный','owner','','text','required')}${field('Методика и версия','method','','text','required')}${field('Упаковка / условия','packaging',revision().packaging?.type||'','','required')}${field('Повторы','repeats',1,'number','min="1" step="1" required')}</div></form><p class="notice">Контрольные точки, показатели и критерии задаются после создания плана. Критерий требует основания.</p>`,`<button class="dark" data-action="save-trial">${id?'Сохранить план':'Создать план'}</button>`);if(id){const t=revision().trials.find(t=>t.id===id),f=$('#trial-form');f.dataset.trial=id;const values={...t,samples:t.samples.map(s=>s.code).join(', '),temperatureC:t.conditions.temperatureC,duration:t.conditions.duration};for(const [key,value] of Object.entries(values)){const input=f.elements.namedItem(key);if(input)input.value=value}}}
async function saveTrial(){const f=$('#trial-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));for(const key of ['name','goal','batch','samples','owner','method','packaging'])if(!d[key]?.trim())throw Error('Все обязательные текстовые поля плана должны быть заполнены.');const codes=d.samples.split(',').map(x=>x.trim()).filter(Boolean);if(new Set(codes).size!==codes.length)throw Error('Коды образцов не должны повторяться.');await changeRevision((r,p)=>{p.stage='Испытания';r.trials??=[];const old=r.trials.find(t=>t.id===f.dataset.trial),samples=codes.map(code=>old?.samples.find(s=>s.code===code)||{id:uid(),code});if(old?.points.some(pt=>!samples.some(s=>s.id===pt.sampleId)))throw Error('Нельзя удалить образец с контрольными точками. Создайте новый план.');const plan={...(old||{}),id:old?.id||uid(),scenario:old?.scenario||scenario,name:d.name.trim(),goal:d.goal.trim(),batch:d.batch.trim(),samples,conditions:{temperatureC:Number(d.temperatureC),duration:Number(d.duration),unit:'ч'},startAt:d.startAt,owner:d.owner.trim(),method:d.method.trim(),packaging:d.packaging,repeats:Number(d.repeats),status:'draft',points:old?.points||[]};if(old)Object.assign(old,plan);else r.trials.push(plan)},'План испытания сохранён');closeDialog()}
function pointDialog(id){const t=revision().trials.find(t=>t.id===id);openDialog('Новая контрольная точка',`<form id="point-form" data-trial="${esc(id)}"><div class="grid">${field('Смещение от начала, ч','offset',0,'number','min="0" step="any" required')}${field('Показатель','indicator','','text','required')}${field('Единица измерения','measurementUnit','','text','required')}${field('Методика и версия','method',t.method,'text','required')}${field('Критерий (границы / соответствие)','criterion','','text','required')}${field('Документ и редакция критерия','criterionSource','','text','required')}<label>Образец<select name="sampleId">${t.samples.map(s=>option(s.id,s.code,'')).join('')}</select></label></div></form>`,`<button class="dark" data-action="save-point">Добавить точку</button>`)}
async function savePoint(){const f=$('#point-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));for(const key of ['indicator','measurementUnit','method','criterion','criterionSource'])if(!d[key]?.trim())throw Error('Заполните показатель, единицу, методику и основание критерия.');await changeRevision(r=>{r.trials.find(t=>t.id===f.dataset.trial).points.push({...d,id:uid(),offset:Number(d.offset),unit:'ч',measurements:[]})},'Точка сохранена');closeDialog()}
function measureDialog(key){const [tid,pid]=key.split('|'),t=revision().trials.find(x=>x.id===tid),pt=t.points.find(x=>x.id===pid),sample=t.samples.find(s=>s.id===pt.sampleId);openDialog('Фактический замер · '+pt.indicator,`<p class="notice">${esc(t.name)} · ${esc(sample?.code)} · партия ${esc(t.batch)}<br>Критерий: ${esc(pt.criterion)} (${esc(pt.criterionSource)})</p><form id="measure-form" data-trial="${tid}" data-point="${pid}"><div class="grid">${field('Значение','value','','number','step="any" required')}${field('Единица','unit',pt.measurementUnit,'text','readonly')}${field('Метод и версия','method',pt.method,'text','required')}${field('Фактическая дата и время','at',localTime(),'datetime-local','required')}<label class="full">Документ-протокол<select name="documentId">${option('','Не приложен','')+state.documents.filter(d=>d.revisionId===revision().id).map(d=>option(d.id,d.name,'')).join('')}</select></label></div></form><p class="field-note">Сохранение фиксирует введённый факт; проверка протокола и заключение требуют отдельной экспертизы.</p>`,`<button class="dark" data-action="save-measure">Сохранить измерение</button>`)}
async function saveMeasure(){const f=$('#measure-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));await changeRevision(r=>{const t=r.trials.find(t=>t.id===f.dataset.trial),pt=t.points.find(p=>p.id===f.dataset.point);pt.measurements??=[];pt.measurements.push({...d,id:uid(),sampleId:pt.sampleId,batch:t.batch,value:Number(d.value),at:new Date(d.at).toISOString(),author:role(),status:'recorded'})},'Измерение сохранено');closeDialog()}
function docsView(){const docs=state.documents.filter(d=>d.productId===product().id&&d.revisionId===revision().id&&(!docFilter||d.documentType===docFilter));return `<div class="row spread"><div><h2>Документы редакции ${esc(revision().version)}</h2><p class="muted">Файлы хранятся локально и связаны с конкретной редакцией</p></div><button class="dark" data-action="upload" ${canEdit()?'':'disabled'}>+ Загрузить файл</button></div><div class="toolbar"><select id="doc-filter" aria-label="Тип документа">${option('','Все документы',docFilter)+['Спецификация','Протокол','Этикетка','Прочее'].map(x=>option(x,x,docFilter)).join('')}</select></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Документ</th><th>Тип</th><th>Добавлен</th><th>Контрольная сумма</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><strong>${esc(d.name)}</strong></td><td>${esc(d.documentType)}</td><td>${date(d.createdAt)}</td><td title="${esc(d.sha256)}">${esc(d.sha256?.slice(0,16)||'Нет данных')}…</td><td><a href="${esc(d.url)}" target="_blank" rel="noopener">Открыть ↗</a><br><a href="${esc(d.url)}" download="${esc(d.name)}">Скачать ↓</a></td></tr>`).join('')}</tbody></table></div>${docs.length?'':'<p class="empty">Документы не найдены. Загрузите файл или измените фильтр.</p>'}</section>`}
function uploadDialog(){openDialog('Загрузка документа',`<form id="upload-form"><div class="grid"><label>Тип документа<select name="documentType">${['Спецификация','Протокол','Этикетка','Прочее'].map(x=>option(x,x,'')).join('')}</select></label><label>Файл<input type="file" name="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.json,.docx,.xlsx" required></label></div></form><p class="notice">Файл будет сохранён на локальном сервере вместе с SHA-256 и ссылкой на эту редакцию. Максимальный размер 10 МБ.</p>`,`<button class="dark" data-action="save-upload">Загрузить</button>`)}
async function saveUpload(){if(!canEdit())throw Error('Пакет редакции зафиксирован.');const f=$('#upload-form'),file=f.querySelector('[name=file]').files[0];if(!file)throw Error('Выберите файл.');if(file.size>10*1024*1024)throw Error('Файл превышает 10 МБ.');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Не удалось прочитать файл.'));r.readAsDataURL(file)});const doc=await uploadAttachment({name:file.name,type:file.type||'application/octet-stream',base64,productId:product().id,revisionId:revision().id,documentType:f.querySelector('[name=documentType]').value});await changeRevision((r,p,next)=>next.documents.push(doc),'Документ загружен');closeDialog()}
function assistantView(){return workflowUI.view()}
function candidateView(){const current=calculate(revision()),c=calculate(candidate.draft);return `<p>База: редакция ${esc(revision().version)} · ${esc(candidate.note)}</p><div class="table-wrap"><table><thead><tr><th>Ингредиент</th><th>Было, кг</th><th>Кандидат, кг</th></tr></thead><tbody>${candidate.draft.ingredients.map((i,n)=>`<tr><td>${esc(i.name)}</td><td>${num(revision().ingredients[n].massKg)}</td><td>${num(i.massKg)}</td></tr>`).join('')}</tbody></table></div><p>Загрузка: ${num(current.inputKg)} → ${num(c.inputKg,4)} кг</p><p>Стоимость исходной загрузки: ${num(current.costInputTotal)} → ${num(c.costInputTotal)} ₽ ${c.costComplete?'':'(неполная)'}</p><p class="notice">Масса и доли изменятся. Сладость, текстура, выход и допустимость требуют проверки; экономия на одинаковый выпуск не подтверждена. Испытания и решения исходной редакции не переносятся.</p><div class="actions"><button class="dark" data-action="accept-candidate" ${candidate.baseId===revision().id&&role()!=='viewer'?'':'disabled'}>Принять · новая редакция</button><button data-action="cancel-candidate">Отменить</button></div>`}
async function runCommand(command){return workflowUI.submit(command)}
function approvalView(){const r=revision(),a=r.approval||{status:'preparation',history:[]},statusNames={preparation:'Подготовка',review:'Параллельная проверка',final:'Итоговое решение',approved:'Утверждено',returned:'Возвращено'};const review=a.status==='review',errors=validateRevision(r);return `<div class="row spread"><div><h2>Утверждение редакции ${esc(r.version)}</h2><span class="badge">${esc(statusNames[a.status]||a.status)}</span></div><div class="actions"><button data-action="check-package">Проверить комплектность</button>${['preparation','returned'].includes(a.status)?`<button class="dark" data-approval="submit" >Отправить на проверку</button>`:''}</div></div><p class="notice">Редакция и пакет фиксируются при отправке. Рецептура и качество проверяются параллельно, финальное решение принимает главный технолог.</p><div class="approval-grid"><div class="step ${['preparation','returned'].includes(a.status)?'active':''}"><span class="step-number">01 / Технолог R&D</span><h3>Подготовка</h3><p>Состав, технология, расчёты, документы и результаты.</p><small>${errors.length?`${errors.length} ошибок рецептуры`:'Рецептура заполнена'}</small></div><div class="parallel"><div class="step ${review?'active':''}"><span class="step-number">02 / Технолог</span><h3>Проверка рецептуры</h3><p>${a.recipe?'Подтверждено · '+date(a.recipe.at):review?'Ожидает решения':'Задача не активна'}</p>${review&&!a.recipe?`<div class="actions"><button class="small dark" data-approval="recipe" >Подтвердить</button><button class="small" data-approval="return" >Вернуть</button></div>`:''}</div><div class="step ${review?'active':''}"><span class="step-number">03 / Специалист качества</span><h3>Проверка качества</h3><p>${a.quality?'Подтверждено · '+date(a.quality.at):review?'Ожидает решения':'Задача не активна'}</p>${review&&!a.quality?`<div class="actions"><button class="small dark" data-approval="quality" >Подтвердить</button><button class="small" data-approval="return" >Вернуть</button></div>`:''}</div></div><div class="step ${a.status==='final'?'active':''}"><span class="step-number">04 / Главный технолог</span><h3>Итоговое решение</h3><p>${a.status==='final'?'Обе проверки пройдены':'После двух положительных проверок'}</p>${a.status==='final'?`<div class="actions"><button class="small dark" data-approval="approve" >Утвердить</button><button class="small" data-approval="return" >Вернуть</button></div>`:''}</div><div class="step ${a.status==='approved'?'active':''}"><span class="step-number">05 / Система</span><h3>Фиксация</h3><p>${a.status==='approved'?'Редакция утверждена и сохранена атомарно':'Ожидает итогового решения'}</p>${a.approvedAt?`<small>${date(a.approvedAt)}</small>`:''}</div></div><section class="card" style="margin-top:24px"><h3>Пакет редакции</h3><p>Запуск: ${esc(a.runId||'Не создан')}</p><p class="id">SHA-256: ${esc(a.packageHash||'Формируется при отправке')}</p>${a.packageSnapshot?`<p>Состав: ${a.packageSnapshot.revision.ingredients.length} строк · документы: ${a.packageSnapshot.documents.length} · зафиксировано ${date(a.packageSnapshot.at)}</p>`:''}<h3>История решений</h3><ul class="list history">${(a.history||[]).map(h=>`<li><time>${date(h.at)}</time> <b>${esc(h.action)}</b> · ${esc(h.role)}${h.comment?' · '+esc(h.comment):''}</li>`).join('')||'<li>Решений ещё нет</li>'}</ul></section>`}
function packageErrors(){const r=revision(),errors=validateRevision(r);if(!r.processSteps.length)errors.push('Технология: добавьте операции.');if(!state.documents.some(d=>d.revisionId===r.id))errors.push('Документы: прикрепите хотя бы один документ редакции.');if(!(r.trials||[]).length)errors.push('Испытания: создайте план с образцом и контрольной точкой.');else if(!r.trials.some(t=>t.points?.length&&t.samples?.length))errors.push('Испытания: план не содержит образцов и контрольных точек.');if(!r.label?.savedAt)errors.push('Этикетка: сохраните черновик редакции.');return errors}
function approvalDialog(action){if(action==='submit'){const errors=packageErrors();if(errors.length){openDialog('Комплектность пакета',`<p class="error">${errors.map(esc).join('<br>')}</p><p>Устраните замечания и повторите отправку.</p>`);return}}openDialog(action==='return'?'Возврат с замечанием':action==='submit'?'Отправка пакета':action==='approve'?'Итоговое утверждение':'Подтверждение проверки',`<p>Продукт: ${esc(product().title)} · редакция ${esc(revision().version)}</p><p class="notice">Действие относится к текущему неизменяемому пакету. Сервер проверит роль и актуальность версии.</p><label>${action==='return'?'Причина возврата (обязательно)':'Комментарий'}<textarea name="approval-comment"></textarea></label>`,`<button class="dark" data-decide="${action}">Подтвердить действие</button>`)}
async function decide(action){const comment=modal.querySelector('[name=approval-comment]').value.trim(),next=clone(state),p=next.products.find(p=>p.id===product().id),r=p.revisions.find(r=>r.id===revision().id),a=r.approval??={status:'preparation',recipe:null,quality:null,history:[]},rr=({recipe:'technologist',quality:'quality',approve:'chief',submit:'rd'})[action]||(a.status==='final'?'chief':'technologist');if(action==='return'&&!comment)throw Error('Укажите причину возврата.');if(action==='submit'){if(!['rd','technologist'].includes(rr)||!['preparation','returned'].includes(a.status))throw Error('Отправка недоступна для этой роли или состояния.');const errors=packageErrors();if(errors.length)throw Error(errors.join('\n'));a.status='review';a.recipe=null;a.quality=null;a.runId=uid();const snapshot=clone(r);delete snapshot.approval;a.packageSnapshot={revision:snapshot,documents:clone(state.documents.filter(d=>d.revisionId===r.id)),at:now()};const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(a.packageSnapshot)));a.packageHash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');p.stage='Утверждение'}else if(action==='recipe'||action==='quality'){if(a.status!=='review'||rr!==(action==='recipe'?'technologist':'quality')||a[action])throw Error('Эта проверка недоступна.');a[action]={decision:'approved',role:rr,at:now(),comment};if(a.recipe&&a.quality)a.status='final'}else if(action==='return'){if(!['review','final'].includes(a.status)||!['technologist','quality','chief'].includes(rr))throw Error('Возврат недоступен.');a.status='returned';a.recipe=null;a.quality=null;a.returnReason=comment;p.stage='Рецептура'}else if(action==='approve'){if(a.status!=='final'||rr!=='chief'||!a.recipe||!a.quality)throw Error('Нужны две положительные проверки и роль главного технолога.');a.status='approved';a.approvedAt=now();p.approvedRevisionId=r.id;p.stage='Утверждение'}a.history??=[];a.history.push({at:now(),action:{submit:'Отправлено на проверку',recipe:'Рецептура подтверждена',quality:'Качество подтверждено',return:'Возвращено на доработку',approve:'Утверждено и зафиксировано'}[action],role:rr,comment,runId:a.runId});await persist(next,'Решение сохранено',rr);closeDialog();render()}
function labelDialog(){const r=revision(),c=calculate(r),label=r.label||{};openDialog('Черновик этикетки',`<div class="two-col"><div class="label-front"><span class="eyebrow">Цифровой продукт · Черновик</span><h2>${esc(product().title)}</h2><p>Масса нетто ${num(r.packaging.portionG)} г</p><small>Редакция ${esc(r.version)} · Не утверждено для печати</small></div><div><h3>Обязательные сведения</h3><p><b>Состав:</b> ${[...r.ingredients].sort((a,b)=>b.massKg-a.massKg).map(i=>esc(i.name)).join(', ')}.</p><p><b>Аллергены:</b> ${esc(c.allergens.join(', ')||'Требует проверки')}</p><p>На 100 г: ${c.nutrition?`${num(c.nutrition.kcal)} ккал; Б ${num(c.nutrition.protein)} г; Ж ${num(c.nutrition.fat)} г; У ${num(c.nutrition.carbs)} г`:'КБЖУ требует подтверждения'}.</p><p class="notice">Срок годности не установлен без утверждённого заключения. Штрихкод и маркировка не сформированы.</p></div></div><hr><form id="label-form"><div class="grid">${field('Изготовитель','manufacturer',label.manufacturer||'')}${field('Адрес изготовителя','address',label.address||'')}${field('Условия хранения','storage',label.storage||'')}${field('Дата / партия (поле печати)','batchPrint',label.batchPrint||'')}</div></form><div id="label-errors" class="notice" style="margin-top:18px">Черновик требует проверки комплектности. Срок годности, реквизиты и обязательные сведения проверяет специалист качества.</div>`,`<button data-action="check-label">Проверить</button><button class="dark" data-action="save-label" ${canEdit()?'':'disabled'}>Сохранить черновик</button>`,true)}
function columnsDialog(){let cols=state.settings.columns;openDialog('Колонки библиотеки',`<p class="muted">Видимость и порядок сохраняются в рабочем пространстве.</p><div id="columns-editor">${cols.map((c,i)=>`<div class="columns-row" data-col-id="${esc(c.id)}"><label class="inline-check"><input type="checkbox" ${c.shown?'checked':''} ${c.id==='title'?'disabled':''}>${esc(columns.find(([id])=>id===c.id)?.[1]||c.id)}</label><button class="small" data-col-move="${i}" data-direction="-1" ${i===0?'disabled':''}>↑</button><button class="small" data-col-move="${i}" data-direction="1" ${i===cols.length-1?'disabled':''}>↓</button></div>`).join('')}</div>`,`<button data-action="reset-columns">Сбросить</button><button class="dark" data-action="save-columns">Сохранить</button>`)}
function readColumns(){return [...modal.querySelectorAll('[data-col-id]')].map(row=>({id:row.dataset.colId,shown:row.querySelector('input').checked}))}
function downloadJson(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function importDialog(){openDialog('Импорт выгрузки',`<p class="notice">Загрузите JSON-досье из ELMA или экспорт приложения. Снимки сырья, ТЗ и исходные редакции сохраняются. API не используется.</p><label>ID исходной карточки (если отсутствует в файле)<input id="import-source-id" placeholder="UUID карточки ELMA"></label><label>JSON-файл<input id="import-file" type="file" accept=".json,application/json"></label><div id="import-preview"></div>`,`<button data-action="export">Экспорт библиотеки</button><button data-action="sample-json">Скачать пример</button><button class="dark" data-action="workflow-import-preview">Проверить файл</button>`)}
async function importFile(){const file=$('#import-file').files[0];if(!file)throw Error('Выберите JSON-файл.');if(file.size>10*1024*1024)throw Error('Размер JSON не должен превышать 10 МБ.');let input;try{input=JSON.parse(await file.text())}catch(e){throw Error('Некорректный JSON: '+e.message)}const next=importProducts(state,input);await persist(next,'Импорт выполнен: новые продукты добавлены');closeDialog();render()}
async function refresh(){const fresh=await loadState();state=fresh;render();toast('Актуальные данные загружены')}
async function handleAction(action){if(await workflowUI.handle(action))return;switch(action){case'close':closeDialog();break;case'refresh':await refresh();break;case'edit-recipe':if(role()==='viewer')throw Error('Наблюдатель не может создавать редакции.');editorDialog();break;case'save-recipe':await saveRecipe();break;case'add-ingredient':readEditor();editor.ingredients.push({lineId:uid(),name:'',massKg:1,phaseId:'main',pricePerKg:null,nutrition:null,allergens:[],properties:{}});drawEditor();break;case'ingredient-catalog':showCatalog();break;case'add-operation':readEditor();editor.processSteps.push({id:uid(),type:'mix',durationMin:null,temperatureC:null,phaseId:'main'});drawEditor();break;case'recalculate':recalcDialog();break;case'apply-recalc':{const f=$('#recalc-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f)),portionG=Number(d.portionG),quantity=Number(d.quantity);if(!Number.isSafeInteger(quantity)||quantity<=0||portionG<=0)throw Error('Количество должно быть целым положительным, масса порции - больше нуля.');calcOptions={portionG,quantity};closeDialog();render();toast('Расчёт партии обновлён');break}case'sensory-edit':sensoryDialog();break;case'save-sensory':await saveSensory();break;case'new-trial':trialDialog();break;case'save-trial':await saveTrial();break;case'save-point':await savePoint();break;case'save-measure':await saveMeasure();break;case'upload':uploadDialog();break;case'save-upload':await saveUpload();break;case'accept-candidate':{if(!candidate||candidate.baseId!==revision().id)throw Error('Кандидат относится к другой редакции. Сформируйте предложение заново.');const accepted=candidate;candidate=null;try{await addRevision(accepted.draft,accepted.note);chat=[];render()}catch(e){candidate=accepted;throw e}break}case'cancel-candidate':candidate=null;render();break;case'label':labelDialog();break;case'check-label':{const d=Object.fromEntries(new FormData($('#label-form'))),missing=Object.entries({manufacturer:'Изготовитель',address:'Адрес',storage:'Условия хранения'}).filter(([k])=>!d[k].trim()).map(([,l])=>l);$('#label-errors').textContent=(missing.length?'Не заполнено: '+missing.join(', ')+'. ':'Реквизиты заполнены. ')+'Срок годности, комплектность маркировки и КБЖУ требуют проверки качества. Статус: черновик.';break}case'save-label':{const d=Object.fromEntries(new FormData($('#label-form')));await changeRevision(r=>{r.label={...d,savedAt:now(),status:'draft'}},'Черновик этикетки сохранён');closeDialog();break}case'check-package':{const errors=packageErrors();openDialog('Комплектность пакета',errors.length?`<p class="error">${errors.map(esc).join('<br>')}</p>`:'<p>Обязательные материалы локального пакета заполнены. Профессиональную проверку выполняют технолог и специалист качества.</p>');break}case'columns':columnsDialog();break;case'save-columns':{const next=clone(state);next.settings.columns=readColumns();await persist(next,'Настройки колонок сохранены');closeDialog();render();break}case'reset-columns':{const next=clone(state);next.settings.columns=columns.map(([id])=>({id,shown:true}));await persist(next);closeDialog();render();break}case'export':downloadJson(state,'Цифровой_продукт_экспорт.json');break;case'import':importDialog();break;case'apply-import':await workflowUI.handle('workflow-import-preview');break;case'sample-json':{const sample=createSeedState();sample.products=sample.products.slice(0,1);sample.products[0].id='local-import-'+uid();sample.products[0].code='local-import-'+Date.now();sample.products[0].revisions.forEach(r=>r.id=uid());downloadJson(sample,'Пример_импорта.json');break}}}
function catalogItems(){const entries=new Map();for(const p of state.products)for(const r of p.revisions)for(const i of r.ingredients){const key=i.name+'|'+(i.specificationVersion||'')+'|'+JSON.stringify(i.nutrition);if(!entries.has(key))entries.set(key,i)}return [...entries.values()]}
function showCatalog(){readEditor();$('#catalog-panel').innerHTML=`<section class="point"><h3>Локальный каталог спецификаций</h3><p class="field-note">Спецификации сохранённых рецептур. Проверяйте применимость и массу после добавления.</p><input id="catalog-search" type="search" placeholder="Поиск сырья" aria-label="Поиск в каталоге"><div id="catalog-list">${catalogItems().map((i,n)=>`<div class="row spread operation" data-catalog-name="${esc(i.name.toLowerCase())}"><div><strong>${esc(i.name)}</strong><br><small>${esc(i.specificationVersion||'Версия не указана')} · ${i.nutrition?num(i.nutrition.kcal)+' ккал / 100 г':'КБЖУ неизвестны'} · ${num(i.pricePerKg)} ₽/кг</small></div><button class="small" data-catalog-pick="${n}">Добавить</button></div>`).join('')}</div></section>`}
function specificationPanel(index){readEditor();const ing=editor.ingredients[index];const old=$('#spec-panel');old?.remove();const panel=document.createElement('section');panel.id='spec-panel';panel.className='point';panel.innerHTML=`<h3>Спецификация: ${esc(ing.name||'Новый ингредиент')}</h3><p class="field-note">На 100 г. Неизвестные показатели оставьте пустыми; известные рассчитываются отдельно.</p><div class="grid">${field('Энергия, ккал','spec-kcal',ing.nutrition?.kcal??'','number','min="0" step="any"')}${field('Белки, г','spec-protein',ing.nutrition?.protein??'','number','min="0" step="any"')}${field('Жиры, г','spec-fat',ing.nutrition?.fat??'','number','min="0" step="any"')}${field('Углеводы, г','spec-carbs',ing.nutrition?.carbs??'','number','min="0" step="any"')}${field('Аллергены через запятую','spec-allergens',ing.allergens?.join(', ')||'')}${field('Технологические свойства JSON','spec-properties',JSON.stringify(ing.properties||{}))}</div><p><button class="small dark" data-save-spec="${index}">Применить спецификацию к черновику</button></p>`;$('#ingredient-editor').append(panel)}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-product],[data-stage]');if(!b)return;try{if(b.dataset.action){await handleAction(b.dataset.action);return}if(b.dataset.product){selectedProduct=b.dataset.product;selectedRevision=null;rememberSelection();workflowUI.clear();calcOptions={};candidate=null;chat=[];location.hash='recipe';render();return}if(b.dataset.stage){filter=b.dataset.stage;render();return}if(b.dataset.group){group=b.dataset.group;render();return}if(b.dataset.scenario){scenario=b.dataset.scenario;render();return}if(b.dataset.editTrial){trialDialog(b.dataset.editTrial);return}if(b.dataset.addPoint){pointDialog(b.dataset.addPoint);return}if(b.dataset.measure){measureDialog(b.dataset.measure);return}if(b.dataset.readyTrial){const t=revision().trials.find(t=>t.id===b.dataset.readyTrial);if(!t.points?.length||!t.samples?.length||!t.method||!t.owner)throw Error('План не готов: нужны образцы, точки, ответственный и методика.');await changeRevision(r=>r.trials.find(x=>x.id===t.id).status='ready','План проверен и готов');return}if(b.dataset.approval){approvalDialog(b.dataset.approval);return}if(b.dataset.decide){await decide(b.dataset.decide);return}if(b.dataset.removeIng!==undefined){readEditor();editor.ingredients.splice(+b.dataset.removeIng,1);drawEditor();return}if(b.dataset.removeOp!==undefined){readEditor();editor.processSteps.splice(+b.dataset.removeOp,1);drawEditor();return}if(b.dataset.moveOp!==undefined){readEditor();const i=+b.dataset.moveOp,j=i+(+b.dataset.direction);[editor.processSteps[i],editor.processSteps[j]]=[editor.processSteps[j],editor.processSteps[i]];drawEditor();return}if(b.dataset.catalogPick!==undefined){readEditor();const source=catalogItems()[+b.dataset.catalogPick];editor.ingredients.push({...clone(source),lineId:uid()});$('#catalog-panel').innerHTML='';drawEditor();toast('Спецификация добавлена в черновик');return}if(b.dataset.spec!==undefined){specificationPanel(+b.dataset.spec);return}if(b.dataset.saveSpec!==undefined){const i=editor.ingredients[+b.dataset.saveSpec],names=['kcal','protein','fat','carbs'],raw=names.map(k=>modal.querySelector(`[name=spec-${k}]`).value);const nutrition=raw.every(x=>x==='')?null:Object.fromEntries(names.map((k,n)=>[k,raw[n]===''?null:Number(raw[n])]));if(nutrition&&Object.values(nutrition).some(v=>v!=null&&(!Number.isFinite(v)||v<0)))throw Error('Значения КБЖУ должны быть неотрицательными.');let properties;try{properties=JSON.parse(modal.querySelector('[name=spec-properties]').value)}catch{throw Error('Свойства должны содержать корректный JSON-объект.')}if(!properties||Array.isArray(properties)||typeof properties!=='object')throw Error('Свойства должны быть JSON-объектом.');i.nutrition=nutrition;i.properties=properties;i.allergens=modal.querySelector('[name=spec-allergens]').value.split(',').map(x=>x.trim()).filter(Boolean);$('#spec-panel').remove();toast('Спецификация добавлена в черновик');return}if(b.dataset.colMove!==undefined){const cols=readColumns(),i=+b.dataset.colMove,j=i+(+b.dataset.direction);[cols[i],cols[j]]=[cols[j],cols[i]];const dom=[...$('#columns-editor').children],node=dom[i];if(j<i)dom[j].before(node);else dom[j].after(node);[...$('#columns-editor').children].forEach((row,n)=>row.querySelectorAll('[data-col-move]').forEach(btn=>{btn.dataset.colMove=n;btn.disabled=(+btn.dataset.direction===-1?n===0:n===cols.length-1)}));return}}catch(error){showError(error)}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='assistant-form'){const command=new FormData(e.target).get('command').trim();if(command)runCommand(command).catch(showError)}});
